import React from 'react';

export default function Hero({ setCurrentPage }) {
  const scrollToFooter = () => {
    window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
  };

  return (
    <div style={{
      background: 'linear-gradient(135deg, #0f4c25 0%, #1a6b36 50%, #0f381d 100%)',
      padding: '90px 20px',
      textAlign: 'center',
      color: '#ffffff',
      position: 'relative',
      overflow: 'hidden',
      boxShadow: 'inset 0 -10px 20px rgba(0,0,0,0.15)'
    }}>
      {/* Subtle Educational Background Pattern Overlay */}
      <div style={{
        position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
        opacity: 0.08,
        backgroundImage: 'radial-gradient(#ffffff 1px, transparent 1px)',
        backgroundSize: '24px 24px',
        pointerEvents: 'none'
      }} />

      <div style={{ maxWidth: '850px', margin: '0 auto', position: 'relative', zIndex: 1 }}>
        <span style={{
          backgroundColor: 'rgba(255,255,255,0.15)',
          color: '#e2e8f0',
          padding: '6px 18px',
          borderRadius: '20px',
          fontSize: '13px',
          fontWeight: 'bold',
          letterSpacing: '1px',
          display: 'inline-block',
          marginBottom: '20px',
          border: '1px solid rgba(255,255,255,0.2)'
        }}>
          🎓 EXCELLENCE IN SECONDARY & HIGHER EDUCATION
        </span>

        <h1 style={{ fontSize: '46px', marginBottom: '20px', fontWeight: '800', lineHeight: '1.2', letterSpacing: '-0.5px' }}>
          AuraPen Saku Education Institute
        </h1>
        
        <p style={{ fontSize: '18px', marginBottom: '40px', color: '#cbd5e1', maxWidth: '680px', marginLeft: 'auto', marginRight: 'auto', lineHeight: '1.7' }}>
          Shaping academic futures through structured guidance, expert faculty, and interactive learning tools. Explore our physical and digital class modules today.
        </p>

        <div style={{ display: 'flex', justifyContent: 'center', gap: '15px', flexWrap: 'wrap' }}>
          <button 
            onClick={() => setCurrentPage('Classes')}
            style={{
              padding: '14px 32px', fontSize: '16px', fontWeight: 'bold', color: '#0f381d', backgroundColor: '#ffffff',
              border: 'none', borderRadius: '30px', cursor: 'pointer', transition: 'all 0.3s ease',
              boxShadow: '0 4px 15px rgba(0,0,0,0.2)'
            }}
          >
            📚 Explore Courses
          </button>
          
          <button 
            onClick={scrollToFooter}
            style={{
              padding: '14px 32px', fontSize: '16px', fontWeight: 'bold', color: '#ffffff', backgroundColor: 'transparent',
              border: '2px solid rgba(255,255,255,0.8)', borderRadius: '30px', cursor: 'pointer', transition: 'all 0.3s ease'
            }}
          >
            📞 Contact Us
          </button>
        </div>
      </div>
    </div>
  );
}
